// Generated by AI (UnitTest MCP)
import { execFileSync } from "node:child_process";
import { mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { afterEach, describe, expect, it } from "vitest";

import {
  SECTIONS,
  foldUnreleased,
  readFragments,
  render,
  sectionOf,
} from "../../../scripts/changelog.mjs";

const script = join(dirname(fileURLToPath(import.meta.url)), "../../../scripts/changelog.mjs");
const directories = [];

const sandbox = () => {
  const root = mkdtempSync(join(tmpdir(), "changelog-"));
  directories.push(root);
  mkdirSync(join(root, "changelog.d"));
  return root;
};

const fragment = (root, name, body) => writeFileSync(join(root, "changelog.d", name), body);

const run = (cwd, args = []) =>
  execFileSync(process.execPath, [script, ...args], { cwd, encoding: "utf8", stdio: "pipe" });

afterEach(() => {
  for (const dir of directories.splice(0)) rmSync(dir, { recursive: true, force: true });
});

describe("sectionOf", () => {
  it("reads the section from the filename prefix", () => {
    expect(sectionOf("fixed-empty-parent.md")).toBe("fixed");
    expect(sectionOf("added-supersede-design.md")).toBe("added");
  });

  it("rejects a section that is not a Keep a Changelog heading", () => {
    expect(sectionOf("banana-thing.md")).toBeNull();
  });

  it("rejects a name with no slug, which would collide immediately", () => {
    expect(sectionOf("fixed.md")).toBeNull();
  });
});

describe("readFragments", () => {
  it("groups fragments by section and ignores the README", () => {
    const root = sandbox();
    fragment(root, "added-one.md", "- **One.** body\n");
    fragment(root, "fixed-two.md", "- **Two.** body\n");
    fragment(root, "README.md", "not a fragment\n");

    const { grouped, problems } = readFragments(join(root, "changelog.d"));

    expect(problems).toEqual([]);
    expect([...grouped.keys()].sort()).toEqual(["added", "fixed"]);
    expect(grouped.get("added")).toEqual(["- **One.** body"]);
  });

  // A fragment that cannot be placed must fail loudly. Dropping it silently
  // would lose the entry at release, which is the one outcome this convention
  // must not have: the whole point is that the change describes itself.
  it("reports an unusable section rather than dropping the entry", () => {
    const root = sandbox();
    fragment(root, "banana-thing.md", "- **Nope.**\n");

    const { problems, grouped } = readFragments(join(root, "changelog.d"));

    expect(grouped.size).toBe(0);
    expect(problems[0]).toMatch(/must be <section>-<slug>\.md/);
  });

  it("reports a fragment with no bullet", () => {
    const root = sandbox();
    fragment(root, "added-prose.md", "just a sentence\n");

    expect(readFragments(join(root, "changelog.d")).problems[0]).toMatch(/at least one/);
  });

  it("returns nothing when the directory does not exist", () => {
    expect(readFragments(join(sandbox(), "absent")).files).toEqual([]);
  });
});

describe("render", () => {
  it("emits sections in Keep a Changelog order, omitting empty ones", () => {
    const grouped = new Map([
      ["fixed", ["- **F.**"]],
      ["added", ["- **A.**"]],
    ]);

    expect(render(grouped)).toBe("### Added\n- **A.**\n\n### Fixed\n- **F.**");
  });

  it("renders nothing when there are no fragments", () => {
    expect(render(new Map())).toBe("");
  });

  it("covers every declared section", () => {
    const grouped = new Map(SECTIONS.map((s) => [s, [`- **${s}.**`]]));
    const headings = [...render(grouped).matchAll(/^### (.+)$/gm)].map((m) => m[1].toLowerCase());
    expect(headings).toEqual(SECTIONS);
  });
});

// Entries written before this convention existed are still sitting under
// `## [Unreleased]`. The first release to use fragments must not lose them.
describe("foldUnreleased", () => {
  it("merges existing unreleased entries with fragments under one heading", () => {
    const unreleased = "\n\n### Fixed\n- **Older entry.**\n";
    const grouped = new Map([["fixed", ["- **From a fragment.**"]]]);

    const merged = foldUnreleased(unreleased, grouped);

    expect(render(merged)).toBe("### Fixed\n- **Older entry.**\n- **From a fragment.**");
  });

  it("keeps a section that exists only in the changelog", () => {
    const merged = foldUnreleased("\n\n### Added\n- **Only here.**\n", new Map());
    expect(render(merged)).toBe("### Added\n- **Only here.**");
  });
});

describe("the command line", () => {
  const changelog = (root, unreleased = "") =>
    writeFileSync(
      join(root, "CHANGELOG.md"),
      `# Changelog\n\n## [Unreleased]\n${unreleased}\n## [0.1.3] - 2026-07-27\n\n### Added\n- **Old.**\n`
    );

  it("--check passes and reports the count", () => {
    const root = sandbox();
    fragment(root, "added-one.md", "- **One.**\n");

    expect(run(root, ["--check"])).toMatch(/1 fragment\(s\) valid/);
  });

  it("--check fails on an unusable fragment", () => {
    const root = sandbox();
    fragment(root, "nope.md", "- **One.**\n");

    expect(() => run(root, ["--check"])).toThrow();
  });

  it("--release folds fragments into a dated section and deletes them", () => {
    const root = sandbox();
    changelog(root);
    fragment(root, "added-one.md", "- **One.**\n");
    fragment(root, "fixed-two.md", "- **Two.**\n");

    run(root, ["--release", "0.1.4"]);

    const text = readFileSync(join(root, "CHANGELOG.md"), "utf8");
    expect(text).toMatch(/## \[0\.1\.4\] - \d{4}-\d{2}-\d{2}/);
    expect(text).toContain("### Added\n- **One.**");
    expect(text).toContain("### Fixed\n- **Two.**");
    expect(text).toContain("## [0.1.3] - 2026-07-27");
    // Unreleased is left empty and in place for the next cycle.
    expect(text).toMatch(/## \[Unreleased\]\n\n## \[0\.1\.4\]/);
    expect(readdirSync(join(root, "changelog.d"))).toEqual([]);
  });

  it("--release keeps entries that were already under Unreleased", () => {
    const root = sandbox();
    changelog(root, "\n### Fixed\n- **Written before fragments existed.**\n");
    fragment(root, "fixed-later.md", "- **Later.**\n");

    run(root, ["--release", "0.1.4"]);

    const text = readFileSync(join(root, "CHANGELOG.md"), "utf8");
    expect(text).toContain("- **Written before fragments existed.**");
    expect(text).toContain("- **Later.**");
  });

  it("--release amends an unpublished same-version candidate", () => {
    const root = sandbox();
    writeFileSync(
      join(root, "CHANGELOG.md"),
      [
        "# Changelog",
        "",
        "## [Unreleased]",
        "",
        "## [0.1.4] - 2026-07-30",
        "",
        "### Added",
        "- **Candidate feature.**",
        "",
        "### Fixed",
        "- **Candidate fix one.**",
        "",
        "  Its detail paragraph must stay separated.",
        "",
        "### Fixed",
        "- **Candidate fix two.**",
        "",
        "## [0.1.3] - 2026-07-27",
        "",
        "### Added",
        "- **Old.**",
        "",
      ].join("\n")
    );
    fragment(root, "fixed-late.md", "- **Late fix.**\n");

    run(root, ["--release", "0.1.4"]);

    const text = readFileSync(join(root, "CHANGELOG.md"), "utf8");
    expect([...text.matchAll(/^## \[0\.1\.4\]/gm)]).toHaveLength(1);
    const candidate = text.slice(text.indexOf("## [0.1.4]"), text.indexOf("## [0.1.3]"));
    expect([...candidate.matchAll(/^### Fixed$/gm)]).toHaveLength(1);
    expect(candidate).toContain("- **Candidate feature.**");
    expect(candidate).toContain(
      "- **Candidate fix one.**\n\n  Its detail paragraph must stay separated."
    );
    expect(candidate).toContain("- **Candidate fix two.**");
    expect(candidate).toContain("- **Late fix.**");
    expect(readdirSync(join(root, "changelog.d"))).toEqual([]);
  });

  it("refuses to release nothing", () => {
    const root = sandbox();
    changelog(root);

    expect(() => run(root, ["--release", "0.1.4"])).toThrow();
  });
});
